From 72525720a1013336613699965c90f68073a83e88 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:32:48 +0100
Subject: [PATCH] shell: don't keep edit mode squeezed after deleting a panel

Deleting a panel from its open Panel Settings left the edit mode desktop
shrunk to one side, because its view is disconnected before deletion and
nothing says the dialog closed. Emit panelBeingConfiguredChanged then.

BUG: 524360
---
 shell/shellcorona.cpp | 4 ++++
 1 file changed, 4 insertions(+)

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..6d500d162e 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -1701,8 +1701,12 @@ void ShellCorona::handleContainmentAdded(Plasma::Containment *c)
         }
         auto view = this->m_panelViews.take(c);
         if (view) {
+            const bool wasConfiguring = view->isUserConfiguring();
             view->disconnect(this);
             delete view;
+            if (wasConfiguring) {
+                Q_EMIT panelBeingConfiguredChanged();
+            }
         }
         const QString snapshotPath = containmentPreviewPath(c);
         if (!snapshotPath.isEmpty()) {
-- 
